import type { InteractionSnapshot, ProcessClient } from '@wright/process-client';
import {
  ProcessUI,
  Section,
  ProgressPanel,
  ResultCard,
  ReasonNotice,
} from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

export default function App({ snapshot, readOnly }: AppProps) {
  const diagnostics = snapshot.diagnostics ?? [];
  const outputs = snapshot.outputs ?? [];

  return (
    <ProcessUI>
      <Section title="Process status">
        <p>
          Read-only SDK qualification review. No engineering acceptance or
          operational action is requested.
        </p>
        {readOnly && <p>The host has also marked this view read-only.</p>}
        <ProgressPanel
          state={snapshot.state}
          observations={snapshot.observations ?? []}
        />
        {diagnostics.length === 0 ? (
          <p>No backend diagnostic reasons are currently reported.</p>
        ) : (
          diagnostics.map((reason, index) => (
            <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />
          ))
        )}
      </Section>

      <Section title="Exact outputs and checks">
        {outputs.length === 0 ? (
          <p>No outputs or checks are currently available.</p>
        ) : (
          outputs.map((output) => (
            <ResultCard key={output.result_id} output={output} />
          ))
        )}
      </Section>
    </ProcessUI>
  );
}
